import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Dream.exe: Can Video Generation Models Dream Executable Robot Manipulation?","description":"","frontmatter":{"title":"Dream.exe: Can Video Generation Models Dream Executable Robot Manipulation?","arxiv":"2606.04811","date":"2026-06-03","authors":"Rui Zhao, Kaiming Yang, Jifeng Zhu, Siyang Chen, Ziqi Wang, Weijia Wu, Kevin Qinghong Lin, Heng Wang, Mike Zheng Shou","categories":"cs.CV","topics":"物理感知视频生成, 视频到动作, 评测基准","outline":[2,2]},"headers":[],"relativePath":"papers/2606.04811.md","filePath":"papers/2606.04811.md","lastUpdated":null}'),e={name:"papers/2606.04811.md"};function l(m,s,i,r,c,o){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="dream-exe-can-video-generation-models-dream-executable-robot-manipulation" tabindex="-1">Dream.exe: Can Video Generation Models Dream Executable Robot Manipulation? <a class="header-anchor" href="#dream-exe-can-video-generation-models-dream-executable-robot-manipulation" aria-label="Permalink to &quot;Dream.exe: Can Video Generation Models Dream Executable Robot Manipulation?&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.04811" target="_blank" rel="noreferrer">2606.04811</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-03</td></tr><tr><td><strong>作者</strong></td><td>Rui Zhao, Kaiming Yang, Jifeng Zhu, Siyang Chen, Ziqi Wang, Weijia Wu, Kevin Qinghong Lin, Heng Wang, Mike Zheng Shou</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把生成的操作视频经点跟踪+深度提升还原成 6-DoF 机器人轨迹并在物理仿真器里真跑一遍，用任务成功率而非观感分数来检验视频模型到底懂不懂物理。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv <strong>v2</strong>（2026-06-04 修订）全文撰写；v1 于 2026-06-03 提交。frontmatter 的日期取首次提交日。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>「视频生成模型正在学习隐式世界模型」这个说法已经被广泛引用，并且成了一整条机器人学习路线的前提：把生成视频当作可扩展的行为先验，用它替代昂贵的真机演示。UniPi、DreamGen、Video Generators are Robot Policies 都建立在这个前提上。</p><p>问题在于这个前提从未被直接检验过。现有视频生成 benchmark 测的是视觉质量、时序一致性和人类审美评分——在这些指标下，一个让机械臂优雅地穿过桌面的模型和一个运动物理上完全成立的模型是无法区分的。论文给出的判据干净利落：如果模型真的内化了操作任务背后的物理规律，那么它生成视频所隐含的轨迹，在机器人执行时就应该完成任务。任务成功与否是二值的、可复现的、不依赖任何打分器。这就把「模型懂不懂物理」从一个解释学问题变成了一个可测量的工程问题。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有 benchmark 分两类。第一类是纯视觉的：EvalCrafter 覆盖视觉质量、运动质量与文视对齐，VBench 把评测拆成时序一致性、主体身份、美学等细粒度维度，T2V-CompBench 关注组合推理。这些工作把「视频看起来自然吗」这个问题做到了很细的粒度，但它们的度量对象自始至终是观感。</p><p>第二类开始触碰物理。VideoPhy 和 PhyGenBench 用 VLM 打分器和人类评分判断生成视频是否描绘了物理上说得通的现象；Kang 等人检验模型对具体物理定律的遵守情况，发现所有当前生成器都存在系统性失败；MIND 评测世界模型的记忆一致性与动作控制。最接近本文的是 WorldSimBench，它加入了一个「隐式操作评测」，问的是生成视频能否经由一个<strong>学到的策略</strong>支持下游任务执行。</p><p>论文对这一族的批评很精确：用视觉分类器度量物理合理性，与「把生成的轨迹交给真实控制器执行、看它成不成功」是范畴上不同的两件事。前者度量的是「一个被训练来识别物理异常的模型觉得像不像」，后者度量的是「这段运动能不能在刚体动力学与接触约束下真正实现」。此外 WorldSimBench 引入的学到的策略是一个中间变量，它自身的容量与训练分布会污染结论。Dream.exe 把中间变量换成一条<strong>无学习成分</strong>的几何提取流水线，让物理执行成为唯一裁判。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先看当时已经成立的三件事。第一，2D 点跟踪（CoTracker）和视频深度估计（DVD 一类）已经足够成熟，能从任意视频里稳定恢复稠密的像素轨迹与时序一致的深度。第二，仿真基准（RoboCasa365 + robosuite/MuJoCo）能把场景状态精确复位，这意味着不同视频模型可以在完全相同的初始条件下被比较。第三，机器人控制里的 operational-space controller 接受的是末端位姿增量序列——这恰好是从视频里最容易还原的东西。</p><p>把这三件事接起来，「视频 → 可执行轨迹」这条链在工程上就通了。剩下的难点是一个概念性的：生成视频里没有 3D 几何、没有接触力、更没有夹爪开合状态，这些必须被推断出来。作者的处理方式是尽可能利用仿真场景的<strong>特权信息</strong>（首帧分割掩码、相机内外参、首帧深度）把不确定性压到最小，只把「运动本身」留给视频模型负责。夹爪时序则从末端与目标物体的相对运动里推断，再用任务标注的交互模式（pick-and-place 需要一次闭合一次张开，pushing 需要零次）约束事件的数量与顺序。</p><p>最后一步是最关键的方法论决策：加两行 oracle 参照。用仿真渲染的真值 rollout 视频跑同一条流水线，得到「流水线本身能做到多好」的上界；再把估计深度换成仿真真值深度，得到「深度估计吃掉了多少性能」。没有这两行，所有绝对数字都无法解释。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>一段视频里的「物理」不在像素里，而在像素所隐含的运动能否被一具真实的机械臂实现。把生成视频还原成末端轨迹丢进物理仿真器执行，接触、摩擦、关节限位、碰撞会自动把所有「看起来对但做不到」的运动筛掉。视觉打分器无法提供这个筛选，因为它本身也只会看。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Level-2 任务「把杯子放进篮子」为例。</p><ol><li><strong>任务准备</strong>。从 RoboCasa365 的 365 个日常操作任务里人工筛选出 101 个 episode，逐个检查相机可见性、物体身份是否有歧义、末端运动是否被遮挡，并逐场景手动调整视角以最大化物体与末端的可见性；不支持底盘导航的任务被剔除。任务按复杂度分三级：Level 1 单物体原子操作（抓放、开关门抽屉、按钮、旋钮），Level 2 多物体状态耦合（放入容器、堆叠、倾倒转移），Level 3 多阶段复合（先开抽屉再取物、先旋灶台旋钮再移锅）。</li><li><strong>视频生成</strong>。每个模型收到同一张初始场景图与同一条任务描述，Level 1/2 生成短片、Level 3 生成长片。指令有两个变体：数据集原始标注的 standard 指令，以及由 Gemini 3 Pro 改写成更贴近生成模型输入分布的 enhanced 指令；正文结果是两者的平均。</li><li><strong>视觉打分</strong>。Gemini 3 Pro 与 Qwen3-VL-Plus 两个 VLM 分别就机器人主体稳定性、物理合理性、任务符合度打分。稳定性用首帧与 75% 处帧并排比较、两问映射到 1–15 的查找表；后两项用 3×2 帧网格打 1–5 分。</li><li><strong>视频转轨迹（五步）</strong>。① 首帧确定末端与被操作物体的区域，有仿真场景时直接用实例分割掩码，否则用 Grounding DINO + SAM2；② 区域内最远点采样出查询点，CoTracker 逐帧跟踪并给出可见性；③ 用 LoRA 微调过的 DVD 估计视频深度（在归一化视差空间训练，损失含掩码重建 + 空间/时序梯度匹配，末端像素加权），预测为仿射深度，再用首帧仿真深度做鲁棒仿射标定；④ 反投影到世界系得到点云，取鲁棒视觉中心，再用初始状态标定把视觉中心平移到 TCP，姿态用 Kabsch 对齐估计并加时序守卫；⑤ 由末端与物体的相对距离、相对速度、共动性等几何线索检测抓/放事件，配合任务先验（如 pick-and-place 恰好 1 次闭合 1 次张开）确定夹爪时序，多阶段任务逐段处理后合并。</li><li><strong>执行与评测</strong>。轨迹转成 delta 6-DoF 动作 + 夹爪指令，在 robosuite 的 operational-space controller 上用 Franka Panda 回放；每次试验前场景精确复位；到达每个 checkpoint 时比较当前位姿与目标位姿，误差超过 5 mm / 0.03 rad 时施加有界的修正动作，避免开环误差累积。</li></ol><p>评测的三条轨道各有指标：轨迹相似度用 HSD（对称 Hausdorff）、DYN（速度分布 Wasserstein-1）、NDTW（归一化 DTW）；可执行性用 E-SR（checkpoint 到达率）、nDTW、Pos95/Rot95、Smth；任务级用 SR-B（二值成功率）与 SR-P（连续进度分），并拆出 Rel / Place / Art / Core 四个子目标。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化集中在轨迹相似度的三个度量上，值得展开，因为它们决定了「像不像」这件事怎样被量化。</p><p>设生成视频还原出的 3D 轨迹为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">m</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>，真值 rollout 轨迹为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0304em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">b</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">b</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>。</p><p><strong>形状偏差</strong>用对称 Hausdorff 距离，它度量的是「最坏情况下两条曲线离得多远」：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathcal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0304em;">B</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1161em;vertical-align:-0.9661em;"></span><span class="mop">max</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size2">{</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.1612em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight">A</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">sup</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9661em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-2.3479em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.0304em;">B</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">in<span style="margin-right:0.0778em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7795em;"><span></span></span></span></span></span><span class="mopen">∥</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.7239em;vertical-align:-0.9739em;"></span><span class="mord mathnormal">b</span><span class="mclose">∥</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.1535em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.0304em;">B</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">sup</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9739em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-2.3557em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight">A</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">in<span style="margin-right:0.0778em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7717em;"><span></span></span></span></span></span><span class="mopen">∥</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord mathnormal">b</span><span class="mclose">∥</span><span class="mord"><span class="delimsizing size2">}</span></span><span class="mord">.</span></span></span></span></span></p><p>直觉：任取生成轨迹上一点，找它到真值轨迹的最近距离；取所有点里最大的那个；再反过来做一遍取较大者。它对整体形状敏感、对时间对齐不敏感。论文在真值轨迹<strong>空间跨度最大的子轨迹</strong>上计算它，避免起止段的静止部分稀释信号。</p><p><strong>动力学偏差</strong>用逐帧速度分布之间的 Wasserstein-1 距离。设两条轨迹的速度经验分布为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">Q</span></span></span></span>，一维情形下</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">Q</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2719em;vertical-align:-0.9119em;"></span><span class="mop"><span class="mop op-symbol large-op" style="margin-right:0.4445em;position:relative;top:-0.0011em;">∫</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:-0.4297em;"><span style="top:-1.7881em;margin-left:-0.4445em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathbb mtight">R</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9119em;"><span></span></span></span></span></span></span><span class="mopen">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">Q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)∣</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">d</span><span class="mord mathnormal">x</span><span class="mpunct">,</span></span></span></span></span></p><p>即两条累积分布函数之间的面积。它回答的是「运动的快慢分布对不对」，与运动发生在什么位置无关——一个把物体以正确路径但两倍速推过去的模型会在这里被扣分。</p><p><strong>时序对齐偏差</strong>用归一化 DTW：先求最优对齐路径 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span> 使累积代价最小，再除以路径长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">∣</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">∣</span></span></span></span>：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">NDTW</span></span><span class="mopen">(</span><span class="mord mathcal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0304em;">B</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.8374em;vertical-align:-1.516em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mopen">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6147em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">⋆</span></span></span></span></span></span></span></span><span class="mclose">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.809em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span><span class="mrel mtight">∈</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6183em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mbin mtight">⋆</span></span></span></span></span></span></span></span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.516em;"><span></span></span></span></span></span><span class="mopen">∥</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">b</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">∥</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">⋆</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.566em;vertical-align:-1.516em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.4em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.809em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span><span class="mrel mtight">∈</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.516em;"><span></span></span></span></span></span><span class="mopen">∥</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">b</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">∥</span><span class="mord">.</span></span></span></span></span></p><p>除以路径长度是为了让长短不一的轨迹可比。三个原始距离都再除以一个由真值轨迹的空间跨度与速度尺度导出的逐任务归一化因子，然后映射到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 的相似度，越高越好。</p><p>这套设计的用意值得点明：三个度量分别隔离了<strong>形状</strong>、<strong>速度分布</strong>、<strong>时序对齐</strong>三个可以独立出错的维度。一个模型可以路径正确但节奏全错，也可以节奏对但路径穿模，单一指标无法区分。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>评测覆盖 8 个模型：闭源 Hailuo 2.3、Kling 3.0、Wan 2.7、SeedDance 2.0、Veo 3.1；开源 Wan 2.2、LTX 2.3；机器人专用 Cosmos Policy。另加 Wan 2.2 在 RoboCasa 非测试集上 LoRA 微调的 2K/7K 步两个变体，以及 Cosmos Policy 的 DefaultCam（三路默认视角）与 BenchCam（主视角替换为 Dream.exe 精调视角）两种配置。</p><p><strong>生成先验里到底有没有物理知识？</strong> 有，但很有限。整体 SR-B 最高的是 SeedDance 2.0（16.5%），其次 Kling 3.0（14.6%）、Wan 2.7（13.6%）。Level 1 上 CosmosPolicy-BenchCam 20.8% 最高，Level 2 上 SeedDance 2.0 与 Wan 2.7 并列 21.4%，Level 3 上<strong>只有 Kling 3.0 拿到非零成功率 6.2%</strong>，其余全部为零。长时程是明确的天花板。</p><p><strong>视觉质量能预测可执行性吗？</strong> 不能，而且是强烈的不能。物理合理性与 SR-B 的 Pearson 相关系数只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.03</span></span></span></span>。最刺眼的两个例子：LTX 2.3 在 VLM 物理合理性上排第一（2.389），SR-B 却排末位（3.9%）；Veo 3.1 任务符合度第一（3.031），Level-1 成功率只有 3.3%。人类评测复现了同样的模式。</p><p><strong>机器人专用训练带来什么？</strong> 带来几何精度，不带来任务成功。CosmosPolicy 在 checkpoint 可执行性上遥遥领先（整体 E-SR 0.750，其余模型 0.40–0.62），位置/旋转跟踪误差也最小，但 Level 2 的 SR-B 是 0.024（DefaultCam）与 0.000（BenchCam），远低于 SeedDance 2.0 与 Wan 2.7 的 21.4%。人类打分给出的解释与之吻合：CosmosPolicy 稳定性 4.418、物理合理性 4.254 都是最高，任务符合度却只有 2.075——它生成的是「看起来非常像机器人在动」但没在做指定任务的视频。</p><p><strong>领域内微调能补上物理吗？</strong> 不能。Wan 2.2 在 RoboCasa 上 LoRA 微调后轨迹相似度确实上升，外观也更像机器人操作，但整体 SR-B 从 4.4% 变到 4.9%（2K）/4.4%（7K），没有实质变化。作者的结论是模型学到了机器人操作的视觉风格，没有学到驱动任务成功的物理约束。</p><p><strong>流水线本身有多少损耗？</strong> 这是两行 oracle 参照的价值。用仿真真值 rollout 视频走同一条流水线，整体 SR-B 只有 0.604；把估计深度换成仿真真值深度后跃升到 0.981。深度估计是当前最大瓶颈，且这个瓶颈对所有通用生成模型是均匀施加的。</p><p><strong>失败模式</strong>归为三类：物体悬浮（object levitation）、幽灵抓取（phantom grasp，物体在无接触的情况下随夹爪移动）、运动学崩塌（kinematic breakdown）。后两类占了绝大多数失败。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版。</strong> Dream.exe 把「视频生成模型是不是世界模型」这个问题重写成「它生成的运动能不能被机器人执行成功」。它在 RoboCasa365 上人工精选 101 个三级难度任务，用一条无学习成分的五步流水线（分割 → CoTracker 点跟踪 → LoRA 微调 DVD 深度 + 首帧仿真深度标定 → 视觉中心到 TCP 标定 + Kabsch 姿态 → 几何线索加任务先验推夹爪时序）把生成视频还原成 6-DoF 动作流，在 robosuite/MuJoCo 里闭环回放。评测 8 个模型后得到三条结论：互联网规模预训练确实编码了可测量的物理知识（若干模型取得非零成功率）；视觉质量与可执行性几乎不相关（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.03</span></span></span></span>）；机器人专用模型几何精度最高但任务成功率反而输给通用生成器。真值 rollout 视频的 oracle 行显示深度估计仍是流水线的主要瓶颈（0.604 vs 真值深度 0.981）。</p><p><strong>三句话版。</strong> 用物理仿真器里的任务成功率取代观感分数来评测视频生成模型。101 个操作任务、8 个模型、三条评测轨道（视觉、轨迹、执行）表明视觉领先者常常执行失败，而视觉一般的模型可以产出物理有效的轨迹。长时程多阶段任务几乎全军覆没，只有一个模型拿到非零成功率。</p><p><strong>一句话版。</strong> 让生成的视频「落地执行」，物理常识这件事就没法靠好看蒙混过去了。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p><strong>整套评测假设「视频转轨迹」流水线的失败与被评测模型的物理错误是可分离的，但论文自己的 oracle 行显示这两者严重纠缠。</strong> 用仿真渲染的真值 rollout 视频——运动完全正确、外观完全干净——走同一条流水线，整体 SR-B 只有 0.604；换成真值深度后是 0.981。也就是说流水线在<strong>运动毫无问题</strong>的情况下也会丢掉约 40% 的成功，绝大部分损失来自深度估计。</p><p>这为什么致命：被评测模型的实际得分区间是 0.039–0.165，全部落在流水线噪声的量级之内。当 SeedDance 2.0 的 16.5% 与 Wan 2.7 的 13.6% 相差 3 个百分点时，无法排除这个差异来自「哪个模型生成的画面更适合 DVD 深度估计」，而不是「哪个模型更懂物理」。这个担忧不是空想：DVD 的 LoRA 是在<strong>仿真渲染的机器人 rollout 视频</strong>上微调的，那么与仿真渲染风格更接近的生成结果（比如在 RoboCasa 上微调过的 Wan 2.2-LoRA，以及本身就在机器人数据上训练的 CosmosPolicy）在深度估计上会占到与物理无关的便宜。论文用「瓶颈对所有通用生成器是均匀施加的」来回应，但这句话恰恰对机器人专用模型与领域内微调模型不成立，而这两类正是论文最重要结论所比较的对象。</p><p>论文提供的证据是那两行 oracle 参照本身——这是很负责任的做法，缺的是一个把深度这一环去掉的对照：例如只用 2D 图像空间的轨迹指标重新排名，看模型排序是否稳定。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现整个 benchmark，只检验「排名是否被深度估计支配」，一周可完成。</p><ul><li><strong>数据</strong>：从 RoboCasa365 里取 20 个 Level-1 任务，用 3 个可公开访问的生成模型（如 Wan 2.2、LTX 2.3 与任一开放 API 模型）各生成一遍视频，同时渲染 20 段真值 rollout 视频。</li><li><strong>实现</strong>：跑通两条并行的轨迹提取路径。路径 A 用单目深度估计（任选一个开源模型，不做 LoRA 微调）；路径 B 直接用仿真真值深度。其余环节（SAM2、CoTracker、TCP 标定、夹爪推断、robosuite 回放）完全共用。</li><li><strong>测量</strong>：三件事。① 每个模型在路径 A 与路径 B 下的 SR-B 与 SR-P；② 两条路径给出的<strong>模型排名</strong>是否一致（用 Kendall <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>）；③ 每个模型生成视频上的深度估计误差（以真值 rollout 的深度误差为参照基线）。</li><li><strong>判据</strong>：若路径 A 与路径 B 的排名 Kendall <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.8</span></span></span></span>，说明深度环节虽然压低绝对分但不改变结论，Dream.exe 的排名可信；若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span>，或某个模型的深度误差显著低于其余（尤其是领域内微调过的模型），则说明当前排名部分是「谁的画面更好估深度」的排名，需要在报告时把深度误差作为协变量控制。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>攻击点一：被论文当作核心发现的「物理合理性与成功率不相关」，很可能是评分器退化造成的伪结论。</strong> 附录 D.1 的逐评委分数暴露了问题：Gemini 3 Pro 给出的物理合理性分数在大量行上恰好等于 1.000（评分下限），而 Qwen3-VL-Plus 在同样的视频上给到 4.3–4.9。正文表 1 报告的是两个评委的平均，于是「物理合理性」这一列几乎全部挤在 1.9–2.4 的窄区间里。一个方差被压缩到接近零、且两个评委严重不一致的变量，与任何东西的相关系数都会接近零。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.03</span></span></span></span> 因此可能主要是在说「这个 VLM 指标本身没有信息量」，而不是「视觉物理判断与可执行性无关」。要让这个发现立得住，需要换用方差正常的物理性度量（例如人类评测里的 Phys. 列，其区间是 1.462–4.254）重算相关性——论文有这份数据却没有报告这个相关系数。</p><p><strong>攻击点二：「通用生成器胜过机器人专用模型」这一结论对相机配置极度敏感。</strong> CosmosPolicy 设计上需要三路视角，论文为它造了 BenchCam 变体（主视角换成 Dream.exe 精调视角，另两路保持默认）。结果是 BenchCam 在 Level 1 拿到全场最高的 SR-B 20.8%，在 Level 2 却是 0.000，而 DefaultCam 在 Level 1 只有 17.9%、Level 2 有 0.024。同一个模型仅因为换了一路相机就在 Level 2 从「几乎为零」变成「完全为零」，说明这些数字位于该模型的失效边缘，不足以支撑「机器人专用训练泛化更差」这样的一般性断言。更合适的对照是给 CosmosPolicy 它训练时使用的原生视角，并在<strong>它的分布内</strong>任务上比较。</p><p><strong>可预测的失败条件</strong>：夹爪时序完全依赖末端与目标物体的相对运动线索，并被任务标注的交互模式先验约束（pick-and-place 恰好一开一合，pushing 零次）。这意味着任何生成视频只要出现「幽灵抓取」——物体在无接触情况下随夹爪移动——几何线索会照样判定抓取成功，而仿真器执行时物体不会跟着走。论文观察到幽灵抓取是主要失败类别之一，这与其说是模型的物理错误被检测出来了，不如说是提取流水线无法把它与真实抓取区分开，从而必然产生执行失败。可以预测：任何倾向于生成「物体粘手」式运动的模型，其 SR-B 会被系统性低估，而这与它对刚体动力学的理解并不直接相关。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>把评测从「视频能否被执行」推进到「视频作为控制器的闭环带宽是多少」。</strong></p><p>(a) <strong>驱动它的局限</strong>：Dream.exe 是彻底开环的——模型看一眼初始图，一次性梦出整段视频，之后再无输入。执行阶段的闭环修正只是在跟踪一条已经写死的轨迹。这个设定天然把长时程任务判死刑（Level 3 上七个模型全零并不意外），也无法回答一个对机器人学更重要的问题：当模型看到自己造成的<strong>真实</strong>后果时，它能不能纠正？现有结论「生成先验编码了有意义的物理知识但长时程失败」，很可能只是在说「开环预测的误差会累积」，这是一个关于开环的结论，不是关于物理理解的结论。</p><p>(b) <strong>可借鉴的相邻领域工具</strong>：一是控制论里的<strong>带宽/相位裕度</strong>思想——不问系统准不准，而问它能在多快的扰动下保持稳定；二是模仿学习里的 <strong>DAgger 式交互评测</strong>，用「在专家分布外的状态上还能不能给出正确动作」来度量策略质量，这比在轨迹上算距离信息量大得多。</p><p>(c) <strong>第一个实验长什么样</strong>：把 Dream.exe 改造成分段闭环。每执行 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 帧后，从仿真器渲染当前真实场景图，重新喂给视频模型，让它续生成下一段，如此循环直到任务结束或超时。核心测量是一条曲线：SR-B 随重规划间隔 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 变化的形状。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord">∞</span></span></span></span> 就是现在的开环设定；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 很小则接近一个视觉伺服控制器。再加一个扰动组：在某个 checkpoint 人为把物体推偏 5 cm，看模型是否在下一段视频里生成纠正性运动，以及需要多少个重规划周期恢复。这条曲线的斜率与扰动恢复率会给出一个全新的量——<strong>生成模型作为闭环控制器的有效带宽</strong>。如果某个模型开环成绩平平但闭环恢复极快，那么当前基于开环成功率的排名就是误导性的；如果所有模型在扰动后都无法恢复，那么「视频生成模型是世界模型」这个说法就应该被限制在「单次前向预测」的意义上，而不能被当作策略先验来用。</p>',62)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
